import re
import pandas as pd
from datetime import datetime

_NUM_RE = re.compile(r'^[+-]?\d+(\.\d{1,2})?$')
_DATE_RE = re.compile(r'^\d{4}-\d{2}-\d{2}$')

_VALID_CURRENCIES = {'USD', 'EUR', 'GBP'}


def _is_null(v):
    if v is None:
        return True
    try:
        if isinstance(v, float) and pd.isna(v):
            return True
    except Exception:
        pass
    try:
        if pd.isna(v):
            return True
    except (TypeError, ValueError):
        pass
    return False


def run(inputs: dict) -> dict:
    raw = inputs['raw_payments']

    reject_rows = []  # list of (row_num, reason)
    passed_rows = []  # list of dicts for rows passing R1-R5

    for _, row in raw.iterrows():
        row_num = row['row_num']
        payment_id = row['payment_id']
        account_id = row['account_id']
        amount_txt = row['amount_txt']
        currency = row['currency']
        pay_date_txt = row['pay_date_txt']

        # R1 MISSING_ID
        if _is_null(payment_id):
            reject_rows.append((row_num, 'MISSING_ID'))
            continue
        trimmed_id = str(payment_id).strip()
        if trimmed_id == '':
            reject_rows.append((row_num, 'MISSING_ID'))
            continue

        # R2 BAD_AMOUNT
        if _is_null(amount_txt):
            reject_rows.append((row_num, 'BAD_AMOUNT'))
            continue
        trimmed_amount = str(amount_txt).strip()
        if not _NUM_RE.match(trimmed_amount):
            reject_rows.append((row_num, 'BAD_AMOUNT'))
            continue
        parsed_amount = float(trimmed_amount)

        # R3 NON_POSITIVE
        if parsed_amount <= 0:
            reject_rows.append((row_num, 'NON_POSITIVE'))
            continue

        # R4 BAD_CURRENCY
        if _is_null(currency):
            reject_rows.append((row_num, 'BAD_CURRENCY'))
            continue
        trimmed_currency = str(currency).strip().upper()
        if trimmed_currency not in _VALID_CURRENCIES:
            reject_rows.append((row_num, 'BAD_CURRENCY'))
            continue

        # R5 BAD_DATE
        if _is_null(pay_date_txt):
            reject_rows.append((row_num, 'BAD_DATE'))
            continue
        trimmed_date = str(pay_date_txt).strip()
        if not _DATE_RE.match(trimmed_date):
            reject_rows.append((row_num, 'BAD_DATE'))
            continue
        try:
            parsed_date = datetime.strptime(trimmed_date, '%Y-%m-%d').date()
        except ValueError:
            reject_rows.append((row_num, 'BAD_DATE'))
            continue

        passed_rows.append({
            'row_num': row_num,
            'payment_id': trimmed_id,
            'account_id': account_id,
            'amount': parsed_amount,
            'currency': trimmed_currency,
            'pay_date': parsed_date,
        })

    # R6 DUPLICATE
    valid_records = []
    if passed_rows:
        passed_df = pd.DataFrame(passed_rows)
        passed_df = passed_df.sort_values('row_num', kind='mergesort')

        seen = {}
        for idx, r in passed_df.iterrows():
            key = r['payment_id']
            if key not in seen:
                seen[key] = r
            else:
                reject_rows.append((r['row_num'], 'DUPLICATE'))

        for key, r in seen.items():
            valid_records.append(r)

    valid_payments = pd.DataFrame(
        valid_records,
        columns=['row_num', 'payment_id', 'account_id', 'amount', 'currency', 'pay_date']
    )
    if not valid_payments.empty:
        valid_payments = valid_payments.sort_values('row_num', kind='mergesort')
    valid_payments = valid_payments[['payment_id', 'account_id', 'amount', 'currency', 'pay_date']].reset_index(drop=True)

    payment_rejects = pd.DataFrame(reject_rows, columns=['row_num', 'reject_reason'])
    if not payment_rejects.empty:
        payment_rejects = payment_rejects.sort_values('row_num', kind='mergesort').reset_index(drop=True)
    else:
        payment_rejects = pd.DataFrame(columns=['row_num', 'reject_reason'])

    return {
        'valid_payments': valid_payments,
        'payment_rejects': payment_rejects,
    }
